(1, 71, 'Member Recharge Benefits', '<h3 style=\"text-align: center; color: #000000;\"><strong>Bonus Rules</strong></h3><div style=\"text-align: center;\"><img src=\"https://pub-628304d7b25d454abf303bfafba6a2e0.r2.dev/ALADDINN/banner/win545.jpg\" alt=\"Bonus Image\" style=\"width: 100%; max-width: 1080px; border-radius: 8px;\"></div><h4 style=\"text-align: center; font-family: Arial, sans-serif; font-size: 14px; color: #ffcc00;\"><strong>1. Minimum Bet Amount:</strong> ?10</h4><h4 style=\"text-align: center; font-family: Arial, sans-serif; font-size: 14px; color: #ffcc00;\"><strong>2. Win Streak:</strong> The win streak should continue without any period skipped.</h4><h4 style=\"text-align: center; font-family: Arial, sans-serif; font-size: 14px; color: #ffcc00;\"><strong>3. Applicable Game:</strong> This bonus is only available on <strong>WINGO</strong>!</h4><h4 style=\"text-align: center; font-family: Arial, sans-serif; font-size: 14px; color: #ffcc00;\"><strong>4. Contact Your Tutor:</strong> To claim the bonus, please reach out to your Tutor.</h4>', 'https://pub-628304d7b25d454abf303bfafba6a2e0.r2.dev/ALADDINN/banner/Banner_2024051416542strake.jpg', 3, 1, '2025-04-27 08:54:14'),
(2, 53, 'Win Streak', '<h3 style=\"text-align: center; color: #000000;\"><strong>Bonus Rules</strong></h3><div style=\"text-align: center;\"><img src=\"https://pub-628304d7b25d454abf303bfafba6a2e0.r2.dev/ALADDINN/banner/win545.jpg\" alt=\"Bonus Image\" style=\"width: 100%; max-width: 1080px; border-radius: 8px;\"></div><h4 style=\"text-align: center; font-family: Arial, sans-serif; font-size: 14px; color: #ffcc00;\"><strong>1. Minimum Bet Amount:</strong> ₹10</h4><h4 style=\"text-align: center; font-family: Arial, sans-serif; font-size: 14px; color: #ffcc00;\"><strong>2. Win Streak:</strong> The win streak should continue without any period skipped.</h4><h4 style=\"text-align: center; font-family: Arial, sans-serif; font-size: 14px; color: #ffcc00;\"><strong>3. Applicable Game:</strong> This bonus is only available on <strong>WINGO</strong>!</h4><h4 style=\"text-align: center; font-family: Arial, sans-serif; font-size: 14px; color: #ffcc00;\"><strong>4. Contact Your Tutor:</strong> To claim the bonus, please reach out to your Tutor.</h4>', 'https://pub-628304d7b25d454abf303bfafba6a2e0.r2.dev/ALADDINN/banner/Banner_2024051416542strake.jpg', 1, 1, '2025-04-27 08:54:14'),
(3, 69, 'Join Telegram', '<h4 style=\"text-align: center; font-family: Arial, sans-serif; font-size: 14px; color: #ffcc00;\"><strong> Bonus is waiting for you, join our telegram channel and get the bonus. </strong></h4><h4 style=\"text-align: center; font-family: Arial, sans-serif; font-size: 14px; color: #ffcc00;\"><strong> To join our official Telegram channel, click on the link given below.</strong> </h4><h4 style=\"text-align: center; font-family: Arial, sans-serif; font-size: 14px; color: #ffcc00;\"><strong> <a style=\"color:#5a5af1;\" href=\"https://t.me/Sikkim3Game\">https://t.me/Sikkim3Game</a></strong> </h4>', 'https://scripthubdemo.online/edited/Banner_20240514165423daily.jpg', 1, 1, '2025-04-27 08:54:14'),
(4, 59, 'LUCKY SPIN TO WIN IPHONE 16 PRO MAX', '<h1 style=\"text-align: center;\"><font color=\"#ffff00\">Click link to apply bonus ➡️ ➡️➡️</font><a href=\"https://t.me/150Rupya_official/wap/indexFDetail.jsp?applyId=20240502001\" target=\"_blank\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 0);\"><b>[link]</b></font></a></h1><p><img src=\"https://pub-628304d7b25d454abf303bfafba6a2e0.r2.dev/ALADDINN/banner/aviator89.jpg\" style=\"width: 1080px;\"></p>', 'https://pub-628304d7b25d454abf303bfafba6a2e0.r2.dev/ALADDINN/banner/avitorgameimage.png', 1, 1, '2025-04-27 08:54:14'),
(5, 47, 'Aladdinn Game Support Funds', '<h3 style=\"text-align: center; color: #000000;\"><strong>Bonus Rules</strong></h3><div style=\"text-align: center;\"><img src=\"https://pub-628304d7b25d454abf303bfafba6a2e0.r2.dev/ALADDINN/banner/vip8585.jpg\" alt=\"Bonus Image\" style=\"width: 100%; max-width: 1080px; border-radius: 8px;\"></div><h4 style=\"text-align: center; font-family: Arial, sans-serif; font-size: 14px; color: #ffcc00;\"><strong>1. Support Fund is given only on the amount of recharge you lose</strong></h4><h4 style=\"text-align: center; font-family: Arial, sans-serif; font-size: 14px; color: #ffcc00;\"><strong>2. Contact your Tutor to claim support fund</strong></h4>', 'https://pub-628304d7b25d454abf303bfafba6a2e0.r2.dev/ALADDINN/banner/Banner_20240514165423VipReward.jpg', 1, 1, '2025-04-27 08:54:14'),
